	@Test
	void declinedPreparationDoesNotMarkTheObservationAsPublished(
			@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		SailRepository repository = repository(path);
		try {
			LmdbStore store = (LmdbStore) repository.getSail();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			try (SailDataset dataset = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
				LmdbEvaluationStrategy.bindExecutionSnapshot(statistics, source, null);
				assertTrue(statistics.feedbackPublicationAllowed());
				var owner = source.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
				var provider = statistics.estimatorRuntime().feedback();
				assertNotNull(provider);
				CommitOnParentUnion observed = observed();
				TupleExpr root = (TupleExpr) observed.getParentNode();
				root.setCostFeedbackTrackingEnabled(true);
				root.setCostFeedbackExpectedRows(10.0d);
				root.setCostFeedbackExpectedWorkRows(100.0d);
				root.setCostFeedbackActualRows(1_000L);
				root.setCostFeedbackActualWorkRows(1_000.0d);
				root.setCostFeedbackCloseCountActual(1L);
				root.setCostFeedbackCompletedActual(true);
				root.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
				observed.provider = provider;
				AtomicReference<Runnable> rollback = new AtomicReference<>();
				observed.beforeParentRead = () -> {
					Object writer = new Object();
					SailSource staged = store.getBackingStore().getExplicitSailSource(writer);
					SailSource.PublicationScope publication = (SailSource.PublicationScope) staged
							.beginPublication(writer);
					var sink = staged.sink(IsolationLevels.READ_COMMITTED);
					rollback.set(() -> {
						publication.fail();
						try (staged; publication; sink) {
							// Close the native writer through its real rollback/publication lifecycle.
						}
					});
					sink.approve(VF.createIRI("urn:legacy-race:rolled-back"), P1, VF.createIRI("urn:legacy-race:value"),
							null);
					sink.flush();
					assertTrue(store.getBackingStore().getTripleStore().hasPendingTripleMutation());
				};
				long before = provider.planningRevision();
				try {
					statistics.recordOperatorOutcome(root);
				} finally {
					if (rollback.get() != null)
						rollback.get().run();
				}
				assertNotNull(rollback.get(), "the accessor must reach the real native publication");
				assertTrue(owner.isCurrentForPhysicalCost(), "rollback preserves the exact paired source");
				assertTrue(statistics.feedbackPublicationAllowed());
				assertEquals(before, provider.planningRevision(), "the declined preparation publishes no cells");
				long operatorMark = observed.getLongMetricActual("optimizer.leoOperatorFeedbackRecordedActual");
				long planMark = root.getLongMetricActual("optimizer.leoPlanFeedbackRecordedActual");
				Files.writeString(path.resolve("declined-publication-marks.txt"),
						"operator=" + operatorMark + " plan=" + planMark + "\n");
				assertTrue(operatorMark <= 0L, "declined operator evidence must remain unrecorded");
				assertTrue(planMark <= 0L, "declined plan evidence must remain unrecorded");
				statistics.recordOperatorOutcome(root);
				assertTrue(provider.planningRevision() > before,
						"the same current observation can publish after rollback");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void aBoundTargetPublishedDuringLegacyPreparationHasItsOwnRevision(
			@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		SailRepository repository = repository(path);
		try {
			LmdbStore store = (LmdbStore) repository.getSail();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			try (SailDataset dataset = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
				LmdbEvaluationStrategy.bindExecutionSnapshot(statistics, source, null);
				assertTrue(statistics.feedbackPublicationAllowed());
				var provider = statistics.estimatorRuntime().feedback();
				assertNotNull(provider);
				long revision = store.getBackingStore().getTripleStore().getDataRevision();
				LogicalLearningKey logical = LogicalLearningKey.of("statement-pattern", "expression", "children",
						"predicates", "v0", "none", "bag", "default");
				LearningApplicability applicability = new LearningApplicability(1L, 0L, "unconditional", revision,
						revision, 1L);
				PhysicalResidualKey physical = PhysicalResidualKey.of("scan", "statement-pattern", "spoc", "scan",
						"none", "none", "none", "unbound");
				var prediction = new RuntimeFeedbackContract.PredictionVector(1d, 1d, 1d, 1d, 0d, 1d, 0d, 0d, 0d, 0d,
						0d, 0d);
				var contract = new RuntimeFeedbackContract(
						new LmdbRuntimeFeedbackDescriptor(null, null, logical, applicability, physical), prediction,
						prediction,
						1d, 1d, 1d, Double.POSITIVE_INFINITY,
						RuntimeFeedbackContract.SemanticKind.ORDINARY,
						RuntimeFeedbackContract.Algorithm.SCAN,
						RuntimeFeedbackContract.Access.FULL_SCAN, 1,
						revision, revision, 1L, RuntimeFeedbackContract.ADMIT_LOGICAL);
				StatementPattern pattern = sp("subject", P1, "object");
				PlanningGraphDomains.capture(pattern, PlanningGraphDomain.defaultGraph());
				var target = statistics.resolveRuntimeFeedbackTarget(pattern, contract);
				assertTrue(target.active());
				target.open();
				target.close(1L, 1d, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
						EvaluationStatistics.TerminationClassification.EXHAUSTED);
				long before = provider.planningRevision();
				AtomicLong nestedRevision = new AtomicLong(-1L);
				CommitOnParentUnion outer = observed();
				outer.provider = provider;
				outer.beforeParentRead = () -> {
					statistics.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
					nestedRevision.set(provider.planningRevision());
				};
				statistics.recordOperatorOutcome(outer);
				Files.writeString(path.resolve("mixed-planning-revision.txt"), "before=" + before
						+ " nested=" + nestedRevision.get() + " after=" + provider.planningRevision() + "\n");
				assertTrue(nestedRevision.get() > before,
						"the already-applied bound target must advance its own revision immediately");
				assertTrue(provider.planningRevision() > nestedRevision.get(),
						"the outer legacy publication advances again");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void nestedObservationsEachAdvanceThePlanningRevision(
			@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		SailRepository repository = repository(path);
		try {
			LmdbStore store = (LmdbStore) repository.getSail();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			try (SailDataset dataset = store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
				LmdbEvaluationStrategy.bindExecutionSnapshot(statistics, source, null);
				assertTrue(statistics.feedbackPublicationAllowed());
				LmdbOperatorFeedbackStats provider = statistics.estimatorRuntime().feedback();
				assertNotNull(provider);
				long before = provider.planningRevision();
				AtomicLong nestedRevision = new AtomicLong(-1L);
				CommitOnParentUnion outer = observed();
				outer.provider = provider;
				outer.beforeParentRead = () -> {
					statistics.recordOperatorOutcome(observed());
					nestedRevision.set(provider.planningRevision());
				};
				statistics.recordOperatorOutcome(outer);
				long after = provider.planningRevision();
				Files.writeString(path.resolve("nested-planning-revision.txt"),
						"before=" + before + " nested=" + nestedRevision.get() + " after=" + after + "\n");
				assertTrue(nestedRevision.get() > before, "the nested observation publishes its own sample");
				assertTrue(after > nestedRevision.get(),
						"the later outer publication must invalidate plans that already saw the nested sample");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void actualPairedSourceMayCommitReentrantlyFromAnAccessor(
			@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		String classpath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		Path log = path.resolve("actual-source-reentrant-child.log");
		Process child = new ProcessBuilder(java, "-ea", "-cp", classpath, Probe.class.getName(),
				path.resolve("store").toString()).redirectErrorStream(true).redirectOutput(log.toFile()).start();
		Files.writeString(path.resolve("child.pid"), Long.toString(child.pid()));
		System.out.println("ACTUAL_SOURCE_REENTRANT_CHILD pid=" + child.pid() + " evidence=" + log);
		boolean settled = child.waitFor(30, TimeUnit.SECONDS);
		if (!settled) {
			Path dump = path.resolve("actual-source-reentrant-thread-dump.txt");
			String jcmd = Path.of(System.getProperty("java.home"), "bin", "jcmd").toString();
			Process diagnostic = new ProcessBuilder(jcmd, Long.toString(child.pid()), "Thread.print", "-l")
					.redirectErrorStream(true)
					.redirectOutput(dump.toFile())
					.start();
			diagnostic.waitFor(10, TimeUnit.SECONDS);
		}
		assertTrue(settled, "unresolved child remains running: pid=" + child.pid() + " evidence=" + log);
		String output = Files.readString(log);
		assertEquals(0, child.exitValue(), output);
		assertTrue(output.contains("ACTUAL_SOURCE_REENTRANT_COMPLETE"), output);
	}

	public static final class Probe {
		public static void main(String[] args) throws Exception {
			SailRepository repository = repository(Path.of(args[0]));
			try {
				LmdbStore store = (LmdbStore) repository.getSail();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
				LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
						.getEvaluationStatistics();
				long revision = statistics.estimatorRuntime().snapshotVersion();
				try (SailDataset dataset = store.getBackingStore()
						.getExplicitSailSource()
						.dataset(IsolationLevels.SNAPSHOT_READ)) {
					var source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
					LmdbEvaluationStrategy.bindExecutionSnapshot(statistics, source, null);
					assertTrue(statistics.feedbackPublicationAllowed(), "the actual paired source is current");
					var owner = source.unwrapDataset(LmdbPinnedReadTxnSource.class).orElseThrow();
					System.out.println("ACTUAL_AUTHORITY_CAPTURED native="
							+ owner.pinnedReadTxn().orElseThrow().nativeTransactionId() + " logical=" + revision);
					CommitOnParentUnion observed = observed();
					AtomicBoolean committed = new AtomicBoolean();
					observed.provider = statistics.estimatorRuntime().feedback();
					assertNotNull(observed.provider);
					observed.beforeParentRead = () -> {
						System.out
								.println(
										"ACCESSOR_COMMIT_ENTERED providerMonitor=" + Thread.holdsLock(observed.provider)
												+ " nativeTripleReaders="
												+ store.getBackingStore()
														.getTripleStore()
														.getTxnManager()
														.lockManager()
														.isReaderActive()
												+ " nativeValueReaders="
												+ store.getBackingStore()
														.valueStore()
														.getTxnManager()
														.lockManager()
														.isReaderActive());
						try (var connection = repository.getConnection()) {
							connection.add(VF.createIRI("urn:legacy-race:new"), P1,
									VF.createIRI("urn:legacy-race:value"));
						}
						committed.set(true);
						System.out.println("ACCESSOR_COMMIT_RETURNED");
					};
					statistics.recordOperatorOutcome(observed);
					assertTrue(committed.get(), "the real commit occurs reentrantly inside the provider monitor");
					assertNotEquals(revision, statistics.estimatorRuntime().snapshotVersion());
					assertNull(
							statistics.estimatorRuntime().feedback().estimate(defaultGraphUnion(), 600, 400, 10, 100),
							"an old observation cannot train the newly committed store");
				}
			} finally {
				repository.shutDown();
			}
			System.out.println("ACTUAL_SOURCE_REENTRANT_COMPLETE");
		}
	}

	private static SailRepository repository(Path path) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		config.setExperimentalQueryOptimizations(true);
		SailRepository repository = new SailRepository(new LmdbStore(path.toFile(), config));
		repository.init();
		return repository;
	}

	private static CommitOnParentUnion observed() {
		CommitOnParentUnion observed = new CommitOnParentUnion(sp("page", P1, "review"), sp("person", P2, "award"));
		Distinct query = new Distinct(observed);
		PlanningGraphDomains.capture(query, PlanningGraphDomain.defaultGraph());
		observed.setCostFeedbackTrackingEnabled(true);
		observed.setCostFeedbackExpectedRows(10.0d);
		observed.setCostFeedbackExpectedWorkRows(100.0d);
		observed.setCostFeedbackReportQErrorThreshold(LmdbOperatorFeedbackStats.DEFAULT_REPORT_Q_ERROR_THRESHOLD);
		observed.setResultSizeEstimate(10.0d);
		observed.setCostEstimate(100.0d);
		observed.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, 100.0d);
		observed.setCostFeedbackActualRows(1_000L);
		observed.setCostFeedbackActualWorkRows(1_000.0d);
		observed.setCostFeedbackCloseCountActual(1L);
		observed.setCostFeedbackCompletedActual(true);
		observed.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1);
		return observed;
	}

	private static Union defaultGraphUnion() {
		Union query = new CommitOnParentUnion(sp("page", P1, "review"), sp("person", P2, "award"));
		PlanningGraphDomains.capture(query, PlanningGraphDomain.defaultGraph());
		return query;
	}

	private static StatementPattern sp(String subject, IRI predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of("_p", predicate, true, true), Var.of(object));
	}

	private static final class CommitOnParentUnion extends Union {
		private Runnable beforeParentRead;
		private LmdbOperatorFeedbackStats provider;

		private CommitOnParentUnion(StatementPattern left, StatementPattern right) {
			super(left, right);
		}

		@Override
		public double getCostFeedbackExpectedRows() {
			Runnable before = beforeParentRead;
			if (before != null && provider != null && Thread.holdsLock(provider)) {
				beforeParentRead = null;
				before.run();
			}
			return super.getCostFeedbackExpectedRows();
		}
	}
